function LadderCompetionMatchDialog:DoMatchStart_()
    CfUtils.PlayAnimator(self.Root, 'Match')
    self:StartMatchCountdown_()

    AppService:GetInstance():SendTcpData(Constants.Packets.LadderMatchStart, {
        sessionId = HttpModule.RequestBodyMeta.SessionId,
        playerId  = GameUtils.GetPlayerId(),
        udid      = DeviceID.DeviceUDID,
    })
end


function LadderCompetionMatchDialog:DoMatchCancel_()
    if KNManager.isConnected then
        AppService:GetInstance():SendTcpData(Constants.Packets.LadderMatchCancel)
    end

    self:ToMatchCancel_()
end


function LadderCompetionMatchDialog:ToMatchCancel_()
    if not isNull(self.doAnimationCo_) then
        cs_coroutine.stop(self.doAnimationCo_)
        self.doAnimationCo_ = nil
    end

    self.isControllable_ = false

    if self.controller then
        self.controller:Close()
    end
end


function LadderCompetionMatchDialog:DoMatchResult_()
    local matchData = self.matchedData_
    local oppoData  = self.matchOppoData_
    local selfData  = self.matchSelfData_

    self.doMatchedToClose_ = true
    self:ClearMatchCountdown_()

    -------------------------------------------------
    -- myself info
    
    ---@type CommonPlayerHeadNode
    local playerHeadLua = CfUtils.GetLuaScr(self.MyselfHeadNode, PlayerHeadLuaPath)
    if not isNull(playerHeadLua) then
        playerHeadLua:FreshBaseUI()
    end

    CfUtils.FillText(self.MyselfTextName, playerComponent.playerDojo.playerName)

    CfUtils.FillText(self.MyselfTextScore, string.format("%s %d", "LV.", playerComponent.playerDojo.level))

    local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
    ---@type LadderGradeVo
    local ladderGradeVo  = ladderCompetionUtils.GetGradeVo(self.ladderHomeDojo_.segment, self.ladderHomeDojo_.subSegment)
    CfUtils.FillImage(self.MyselfImgGrade, ladderGradeVo.icon)
    local starCount = checkNumber(selfData.subSegment)
    for i = 1, 5 do
        local child = self.MyStarGroup.transform:GetChild(i - 1)
        if i <= starCount then
            KTool.SetActive(child.gameObject,true)
        else
            KTool.SetActive(child.gameObject,false)
        end
    end
    -------------------------------------------------
    -- others info

    ---@type CommonPlayerHeadNode
    local othersHeadLua = CfUtils.GetLuaScr(self.OthersHeadNode, PlayerHeadLuaPath)
    if not isNull(othersHeadLua) then
        othersHeadLua:FreshAvatarFrame(oppoData.avatar, oppoData.avatarFrame)
    end

    CfUtils.FillText(self.OthersTextName, tostring(oppoData.name))

    CfUtils.FillText(self.OthersTextScore, string.format("%s %d", "LV.", oppoData.level))

    ---@type LadderGradeVo
    local ladderGradeVo  = ladderCompetionUtils.GetGradeVo(oppoData.segment, oppoData.subSegment)
    CfUtils.FillImage(self.OthersImgGrade, ladderGradeVo.icon)
    local starCount = checkNumber(oppoData.subSegment)
    for i = 1, 5 do
        local child = self.OtherStarGroup.transform:GetChild(i - 1)
        if i <= starCount then
            KTool.SetActive(child.gameObject,true)
        else
            KTool.SetActive(child.gameObject,false)
        end
    end
    -------------------------------------------------
    -- do animation flow
    
    self.doAnimationCo_ = cs_coroutine.start(function()
        local animTime = 0

        -- play animator : Complete
        CfUtils.PlayAnimator(self.Root, 'Complete')
        animTime = CfUtils.GetAnimatorTime(self.Root, 'LadderCompetionMatchDialogComplete')
        coroutine.yield(CS.UnityEngine.WaitForSeconds(1))

        -- show others guessAnime
        --CfUtils.SetActive(self.OthersGuessRoot, true)

        -- play animator : Number
        CfUtils.PlayAnimator(self.Root, 'Number')
        animTime = CfUtils.GetAnimatorTime(self.Root, 'LadderCompetionMatchDialogNumber')
        coroutine.yield(CS.UnityEngine.WaitForSeconds(animTime))
        self.doAnimationCo_ = nil
        self:ShowPreBattleLoading_()
    end)

    -------------------------------------------------

end

