function LadderCompetionMatchDialog:StartMatchCountdown_()
    self:ClearMatchCountdown_()
    self.matchCdHandler_ = CDTimerModule:AddCD(1, function(countTimes, timerId)
        CfUtils.FillText(self.TextMatchTime, self.matchWaitSeconds_ - countTimes)
        if countTimes <= 0 then
            GameUtils.Toast(localize('匹配超时，请重新匹配'))
            self:DoMatchCancel_()
        end
    end, self.matchWaitSeconds_, true, true)
end


function LadderCompetionMatchDialog:ClearMatchCountdown_()
    if not isNull(self.matchCdHandler_) then
        CDTimerModule:RemoveCD(self.matchCdHandler_)
        self.matchCdHandler_ = nil
    end
end

