function LadderCompetionMatchDialog:OnClickCancelButtonHandler_()
    if not self.isControllable_ then return end
    self:DoMatchCancel_()
end


function LadderCompetionMatchDialog:OnPVPMatchResultHandler(packetId, data)
    if packetId == Constants.Packets.LadderMatchResult then
        local matchResult  = checkInt(data.result)
        local errorMessage = checkString(data.msg)
        if matchResult == 1 then
            self.matchedData_ = checkTable(data)

            -- save oppo data
            self.matchOppoData_ = self.matchedData_.confront or {}

            -- create mySelf data
            self.matchSelfData_ = {
                playerId    = playerComponent.playerDojo.playerId,
                name        = playerComponent.playerDojo.playerName,
                level       = playerComponent.playerDojo.level,
                avatar      = playerComponent.playerDojo.playerAvatar,
                avatarFrame = playerComponent.playerDojo.playerAvatarFrame,
                segment     = self.ladderHomeDojo_.segment,
                subSegment  = self.ladderHomeDojo_.subSegment,
                score       = self.ladderHomeDojo_.score,
                lastCards   = {},
                cards       = {},
            }
            local teamInfoData = teamComponent:GetTeamInfoByQuestId(LadderQuestId, 1)
            ---@param teamMemberDojo TeamMemberDojo
            for cardIndex, teamMemberDojo in ipairs(teamInfoData.cardsInfo) do
                local cardId = teamMemberDojo.refId
                self.matchSelfData_.cards[cardIndex] = cardComponent:GetCardById(cardId)
            end

            -- do match result
            self:DoMatchResult_()
        else
            if matchResult == 3 then
                GameUtils.SecondConfirm(localize('当前长时间不在游戏中需要退出游戏重新进入'), function()
                    ---退到登录页面
                    CS.UnityEngine.Application.Quit()
                    ---退到登录页面的逻辑暂缓
                end, function()
                    CS.UnityEngine.Application.Quit()
                end)
            else
                errorMessage = string.len(errorMessage) > 0 and ('\n' .. errorMessage) or ''
                GameUtils.Toast(localize('匹配发生意外，请重新匹配') .. errorMessage)
            end
            self:DoMatchCancel_()
        end
    end
end

function LadderCompetionMatchDialog:OnPVPCancelBattleHandler_()
    -- 服务器匹配成功之后，客户端收到匹配成功之前，这两者中间的时候，对方点了取消匹配的按钮
    if self and self.controller then
        if BattleViewMgr == nil then
            if isNotNull(self.doAnimationCo_) then
                CoStop(self.doAnimationCo_)
            end
            if isNotNull(self.battleCo) then
                CoStop(self.battleCo)
            end
            -- 关闭界面
            self.controller:Close()
        end
    end
end

function LadderCompetionMatchDialog:OnGameTcpDisconnectHandler_()
    GameUtils.Toast(localize('发生网络波动，请重新匹配'))
    UIModule.CloseDialogById(Constants.UITypeIds.PvpFingerGuessingDialog)
    self:ToMatchCancel_()
end


function LadderCompetionMatchDialog:OnAppToBgHandler_()
    if self.doMatchedToClose_ then
        Events.Broadcast(Constants.EventNames.PVPFingerGuessingCancel)
    else
        self:DoMatchCancel_()
    end
end


